"""Serialize the authored establishment questions with subject-specific semantics."""
import json
import re
from pathlib import Path

RUN=Path(__file__).resolve().parent
def refs(*n):
    return [f'SRC-{i:03d}' for i in n]

def build():
    rows=[
        ('Service Annual Survey glossary','US Census Bureau','https://www.census.gov/programs-surveys/sas/about/glossary.html','Public page inspected 2026-09-09; revision pin pending','Selected establishment, firm and disclosure passages; US statistical scope only.'),
        ('Etablissement','Insee','https://www.insee.fr/fr/metadonnees/definition/c1377','2020-11-10','Full short definition: geographic production unit and legal-unit dependency; France-specific.'),
        ('Siret number','Insee','https://www.insee.fr/en/metadonnees/definition/c1841','Displayed date 04/12/2019; locale interpretation not assumed','Full short identifier definition, distinct from legal-unit identity.'),
        ('The Organization Ontology','W3C','https://www.w3.org/TR/vocab-org/','Recommendation; public version inspected 2026-09-09; dated URI pin pending','Selected organization, unit and site clauses; no complete delegation semantics.'),
        ('Global Location Number','GS1','https://www.gs1.org/standards/id-keys/gln','Public overview indexed text inspected 2026-09-09','Identifier may describe party, function or location; direct HTTP 403 and allocation rules uninspected.'),
        ('State Transition and Validation Rules','GLEIF','https://www.gleif.org/lei-data/access-and-use-lei-data/level-2-data-reporting-exceptions-2-1-format/2025-07-03_state-transition-validation-rules_2.8.5_final.pdf','Version 2.8.5 Final 2025-07-03','Selected pages 52-53 and 99: international branch can aggregate offices in a host jurisdiction; current replacement release not checked.'),
        ('LocalBusiness','Schema.org','https://schema.org/LocalBusiness','Public type page inspected 2026-09-09; release pin pending','Selected definition, branch, contact and opening-hours properties; discovery projection, not legal standing.'),
        ('PROV-DM','W3C','https://www.w3.org/TR/prov-dm/','Recommendation 2013-04-30','Attribution and derivation alignment; no access grants or truth ranking inferred.'),
        ('Date and Time on the Internet: Timestamps','IETF','https://www.rfc-editor.org/rfc/rfc3339','RFC 3339 July 2002','Seconds and offset for instants; recurrence requires a separate local timezone/calendar contract.'),
    ]
    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type='standard' if i in (4,6,8,9) else 'public-authority' if i in (1,2,3) else 'first-party-doc',primary_source=True,authority_tier=1 if i in (1,2,3,4,6,8,9) else 2,accessed_at='2026-09-09T19:55:00Z',relevance=r) for i,(t,o,u,v,r) in enumerate(rows,1)]
    design=(RUN/'question-design.md').read_text(encoding='utf-8')
    ids=['establishment-kind','operator-attachment','site-binding','presence-recognition','local-activity','service-availability','local-mandate','registration-evidence','presence-continuity','reporting-scope','presence-governance','presence-exchange']
    kinds=[['classification','identity','evidence'],['ownership','relationship','lifecycle'],['spatial','classification','relationship'],['identity','evidence','quality'],['definition','classification','relationship'],['temporal','constraint','state'],['authority','constraint','privacy'],['identity','authority','exception'],['event','lifecycle','provenance'],['definition','measurement','composition'],['ownership','quality','access'],['interoperability','identity','validation']]
    bundles=[]
    count=0
    for group in re.split(r'(?m)^## ',design)[1:]:
        title=group.split('\n',1)[0]
        layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            name,body=section.split('\n',1)
            qtext,fieldtext=body.split('Candidate fields:',1)
            questions=re.findall(r'(?m)^- (.+\?)$',qtext)
            fields=re.findall(r'([a-z][a-z-]*)\s*\{([^}]+)\}',fieldtext.split('Sources:',1)[0])
            sr=re.findall(r'SRC-\d{3}',fieldtext.split('Sources:',1)[1])
            assert len(questions)==len(fields)==3
            lid=ids[count]
            desc='Source-qualified organizational presence record for '+name.lower()+'. No universal equivalence of branch, legal entity and premises is implied.'
            elements=[dict(id=lid+'-'+k,name=k,description='Proposed structured answer group: '+v+'. Preserve explicit unknowns and master references; executable nested schema is deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr) for k,v in fields]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[count][i],answer_data=[elements[i]['id']]) for i,q in enumerate(questions)],data_elements=elements,artifacts=[dict(id=lid+'-evidence',name=name+' evidence',description='Authorized register extracts, observations or mapping receipts supporting '+name.lower()+', retaining scope and dates.',media_or_form=['application/json','application/yaml','text/markdown','external reference'],serial=True,identity_strategy='Master-system ID first, then issuer-qualified UUID; revision and digest separately. A timestamp is not unique identity.',source_refs=sr)],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr,findings=[finding]))
            count+=1
        assert len(layers)==2
        bundles.append(dict(id='presence-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Organizational operating-presence concerns: '+title.lower()+'.',rationale='Groups two subject-specific records without remastering buildings, organizations or services.',source_refs=sorted(set(s for layer in layers for s in layer['source_refs'])),layers=layers))
    assert count==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-org-011',model_id='WM-ORG-011',name='Business Establishment / Branch',entry_kind='aggregate',purpose='Describe an organization operating presence with explicit source-defined kind, operator, sites, local activity and evidence.',scope_statement='One record represents an establishment, branch or outlet under a declared definition and jurisdiction. These kinds are not interchangeable. Organizational identity, physical premises, statutory authority and service execution retain their own masters.',in_scope=['Issuer-qualified presence identity and organizational attachment','Time-bound sites, local activity, recognition and availability','Scoped mandate, register evidence, continuity, reporting grain and governed exchange'],out_of_scope=['Treating every branch as one premises or a separate legal person','Automatic registration, permit determination or service execution','Remastering building geometry, organization accounts or private personnel records'],boundary_notes=[dict(neighbor=n,distinction=d,source_refs=s) for n,d,s in [('WM-ORG-001 Organization','Proposed REFERENCE: operating presence is not the entire parent or legal entity.',refs(1,2,4)),('Physical premises and organizational unit','A site can host several units; an organizational unit is not its address.',refs(4,5)),('Statistical establishment versus international branch','Source-qualified kind is mandatory; GLEIF branch scope may encompass several offices.',refs(1,2,6)),('Service, permit and reporting masters','Keep scoped references; public listing is not service permission or proof of legal standing.',refs(6,7,8))]])
    services=dict(
        dimension=dict(owner_package_requirements=['Identify the Dimension owner and operating-presence data steward.','Declare organization, register, site and service masters.','Bind local access, delegation, change and retention policies before use.'],namespace_guidance='Issuer-qualified presence identifiers with kind and profile; never infer identity from address, trading name or a parent identifier alone.',registry_links=['Model registry','Organization and operating-presence registry','Site and service registries','Evidence and change registry']),
        canon_and_patch=dict(canonicalization_rules=['Preserve the source-defined unit kind, jurisdiction, master and valid period.','Do not merge branch, site and legal entity from a common identifier or address alone.'],patch_rules=['Apply authorized namespaced extensions against a pinned base digest; validate before and after changes.','Append corrections and succession decisions; reject concurrent stale-base replacement.'],compatibility_rules=['Changed unit grain or identity semantics requires explicit migration and preserved old references.','Mappings record non-equivalence and loss instead of claiming universal same-as.']),
        artifact_rules=dict(identity_priority=['Authoritative master-system identifier','Governed issuer-qualified URI or global identifier','Dimension-issued UUID with issuer context'],timestamp_rule='RFC 3339 with seconds and explicit offset or Z for instants; preserve effective versus recorded time. Recurring hours require timezone and calendar semantics separately.',serial_naming_rule='Artifact-kind prefix, escaped stable ID and revision; optional timestamp is a display aid, not identity.',integrity_rule='Pin exact-byte digest and source revision; hash identity does not prove operating truth or legal standing.'),
        policies=['Unit kind and jurisdiction profile are mandatory before comparing reporting units.','Public names, contacts or hours never establish local mandate, permits or legal personality.','Use permission-scoped references for premises accessibility and private contacts.','Preserve conflicting assertions with provenance; no silent latest-wins rule.'],
        crud=dict(read=['Read owner policy, source kind, pinned model, organizational attachment and freshness before relying on a presence record.'],create=['Create from authorized identity and operator evidence; record unknown site, status and authority instead of inventing them.'],update=['Append versioned observations or corrections with expected-base check; registration and operational changes require master receipts under actual authority.'],delete=['Apply retention and legal-hold policy, preserving authorized tombstones and succession links; do not cascade into organization, building or service masters.']),
        roles=[dict(name=n,responsibilities=[d]) for n,d in [('Dimension owner','Defines namespace and federation authority.'),('Presence steward','Maintains unit kind, source identity and operator bindings.'),('Local operator','Supplies local service and presence evidence within scope.'),('Reviewer','Checks conflicting registrations, continuity and mappings.'),('Custodian','Maintains authorized cache freshness and retention.')]],
        access=dict(default_rule='Deny unless owning Dimension grants the specific purpose and scope.',scopes=['bundle','layer','finding','artifact'],exceptions=['Only explicit recorded time-limited delegation; a public listing does not waive private source restrictions.'],audit_requirements=['Log actor, scope, purpose, evidence version, correction and disclosure decisions without secrets.']),
        agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension owner and policy','Pinned model and source-defined kind','Organization/site/service dependencies and freshness','Evidence, validation, extensions, safe changes and retirement']))
    fnrows=[
        ('resolve-presence','Resolve operating presence','Disambiguate a presence using source-qualified identity.',['Identifiers','Kind and jurisdiction','Authorized evidence'],['Qualified match or contested candidates'],['Issuer and profile known'],['Do not merge by address or parent name alone'],refs(1,3,5,6)),
        ('locate-presence','Locate current sites','Resolve time-bound site roles and evidence.',['Presence revision','Target instant'],['Site references with roles and uncertainty'],['Authorized site evidence'],['No branch equals building inference or physical-access authorization'],refs(4,5,6)),
        ('describe-local-service','Describe usable local services','Combine service references with qualified availability.',['Local service bindings','Calendar and exception evidence'],['Time-qualified service availability or unknown'],['Fresh evidence and declared timezone'],['Opening hours do not prove eligibility, capacity or authority'],refs(7,9)),
        ('check-mandate-evidence','Check authority evidence completeness','Inspect scoped mandate and registration evidence, not legal validity.',['Role and register references','Requested action scope'],['Evidence gaps or referenced authority record'],['Reader authorized; applicable profile specified'],['No permit or legal-standing determination from vocabulary data'],refs(4,6,8)),
        ('record-continuity','Record organizational presence change','Preserve relocation, closure and succession decisions.',['Prior revision','Change evidence','Issuer policy'],['Successor revision and explicit continuity decision'],['Authorized change and expected-base check'],['No silent identity reuse or retroactive overwrite'],refs(2,4,5,9)),
        ('exchange-presence','Exchange with unit-grain losses','Map presence into a target vocabulary without erasing distinctions.',['Source profile','Target mapping','Authorized fields'],['Projection and loss or rejection report'],['Unit-kind and identifier mapping reviewed'],['Shared code never proves universal entity equivalence'],refs(1,3,4,5,6,7)),
    ]
    functions=[dict(id=i,name=n,description=d,inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,d,a,b,c,e,s in fnrows]
    composition=[dict(target=t,relation=r,purpose=p,required=req,source_refs=s) for t,r,p,req,s in [('WM-ORG-001','REFERENCE','Resolve operator and parent organization while preserving distinct presence identity; proposed typed relation.',True,refs(1,2,4)),('https://www.w3.org/TR/vocab-org/','ALIGN','Candidate organization, unit and site mapping; not complete mandate conformance.',False,refs(4)),('https://www.gs1.org/standards/id-keys/gln','ALIGN','Qualify party/function/location identifiers without identity conflation.',False,refs(5)),('https://schema.org/LocalBusiness','ALIGN','Optional public discovery projection of local services and contacts.',False,refs(7))]]
    holds=['Claude and Grok each timed out once; no independent external review. Codex-only research must remain reviewable-draft.','Establishment, branch and outlet profiles remain distinct; future separation into models needs controlled migration.','GS1 overview is indexed text only with direct HTTP 403; allocation rules and exact mutable source release pins are not fully verified.','GLEIF 2.8.5 selected clauses are historical reference evidence; current replacement releases and full legal applicability remain unverified.','No complete statutory inventory, nested executable schema, registry identity resolver, legal-standing verifier or real multi-registry fixtures delivered.','Actual premises accessibility, service capacity, delegation and retention must be established by adopters, not inferred from public listings.']
    dims=[('identity','Source-defined unit kind, issuer and disambiguation.'),('classification','Activity scheme, edition and allocation scope.'),('direct properties','Operating status, local activity and organizational attachment.'),('recognition','Public identity and observed presence with ambiguity.'),('capabilities','Proposed local service and information operations with authority limits.'),('lifecycle','Opening, suspension, relocation, closure and succession.'),('temporal','Effective versus recorded time; schedule exceptions and freshness.'),('relationships','Operator, parent, premises and service remain referenced.'),('provenance','Register and observation sources remain distinct.'),('ownership','Data owner, operating organization and custodian distinguished.'),('validation','Co-location and multi-site fixtures proposed; no execution proof.'),('access','Contact, source and reporting disclosures scoped.'),('retention','Policy-bound correction and tombstone history.'),('interoperability','Explicit unit grain and identifier mapping losses.')]
    coverage=dict(claim='Proposed source-grounded organizational operating-presence contract, not exhaustive statutory coverage, legal advice or an executable registry adapter.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='Physical geometry and material',status='not-applicable',notes='Organizational presence is not a building; physical premises characteristics remain delegated references.'),dict(dimension='Executable and independent conformance',status='gap',notes='Runtime fixtures, full normative mappings and independent review deferred.')],known_omissions=holds,conflicts=[],regional_assumptions=['Statistical and registration terminology depends on source and jurisdiction. No universal branch legal standing or one-location rule is asserted.'],adversarial_checks=['Reject establishment, enterprise and legal entity conflation.','Reject branch equated to one building or registered office.','Reject shared GLN, Siret or address as unqualified same-as.','Reject franchise or brand relationship as proven ownership.','Reject opening hours as service capacity or authorization.','Reject relocation as automatic identity continuity.','Reject suppressed local metrics as zero or duplicate parent totals.','Reject stale public contact as valid mandate.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
